import hashlib
import os
import json

# Dosya yolu
DATABASE_FILE = "users.json"

# Veritabanını yükle
def load_database():
    if os.path.exists(DATABASE_FILE):
        with open(DATABASE_FILE, "r") as file:
            return json.load(file)
    return {}

# Veritabanını kaydet
def save_database(database):
    with open(DATABASE_FILE, "w") as file:
        json.dump(database, file, indent=4)

# Şifreyi tuzla karma
def hash_password(password, salt):
    return hashlib.sha256((password + salt).encode()).hexdigest()

# Yeni kullanıcı ekle
def add_user(username, password):
    database = load_database()
    if username in database:
        print("Bu kullanıcı adı zaten mevcut.")
        return False
    salt = os.urandom(32).hex()
    hashed_password = hash_password(password, salt)
    database[username] = {"salt": salt, "password": hashed_password}
    save_database(database)
    print("Kullanıcı başarıyla eklendi.")
    return True

# Kullanıcı doğrulama
def authenticate_user(username, password):
    database = load_database()
    if username not in database:
        print("Kullanıcı adı bulunamadı.")
        return False
    stored_salt = database[username]["salt"]
    stored_hash = database[username]["password"]
    hashed_input = hash_password(password, stored_salt)
    if hashed_input == stored_hash:
        print("Giriş başarılı.")
        return True
    else:
        print("Şifre yanlış.")
        return False

# Ana menü
def main():
    while True:
        print("\n1. Kullanıcı Ekle")
        print("2. Giriş Yap")
        print("3. Çıkış")
        choice = input("Seçiminiz (1/2/3): ").strip()
        if choice == "1":
            username = input("Kullanıcı adı: ").strip()
            password = input("Şifre: ").strip()
            add_user(username, password)
